<?php
namespace App\Livewire;
use App\Models\Announcement;use App\Models\Term;use App\Models\User;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Mail;use Livewire\Attributes\Layout;use Livewire\Component;use Throwable;
#[Layout('layouts.app')] class Communications extends Component{public string $title='',$message='',$audience='parents';public function send():void{$this->validate(['title'=>'required|string|max:255','message'=>'required|string|max:5000','audience'=>'required|in:all,parents,staff,teachers']);$school=Auth::user()->school;$term=$school->currentTerm();$users=User::where('school_id',$school->id)->whereNotNull('email')->when($this->audience==='parents',fn($q)=>$q->where('role','parent'))->when($this->audience==='teachers',fn($q)=>$q->where('role','teacher'))->when($this->audience==='staff',fn($q)=>$q->whereIn('role',['admin','academic_admin','registrar','bursar','teacher']))->get();if($users->isEmpty()){$this->addError('audience','No email recipients exist for this audience.');return;}try{$announcement=Announcement::create(['school_id'=>$school->id,'term_id'=>$term?->id,'created_by'=>Auth::id(),'title'=>$this->title,'message'=>$this->message,'target_audience'=>$this->audience,'recipient_count'=>$users->count(),'sent_at'=>now()]);foreach($users as $user)Mail::raw($announcement->message,fn($mail)=>$mail->to($user->email)->subject($school->name.': '.$announcement->title));$this->reset(['title','message']);$this->audience='parents';session()->flash('status','Announcement sent to '.$users->count().' recipient(s).');}catch(Throwable $exception){report($exception);session()->flash('error','Announcement was not sent. Check email settings and try again.');}}public function render(){return view('livewire.communications',['announcements'=>Announcement::where('school_id',Auth::user()->school_id)->latest()->get(),'pageTitle'=>'Communications']);}}
